#!/usr/bin/env python3
"""validate-kanban.py

Deterministic integrity check for a geeky-plan kanban.md against the tasks/ folder.
Replaces LLM self-report ("I updated the board") with a fail-stop check.

Checks (errors fail the run; warnings do not):
  ERROR   - a task file in tasks/ is not placed in any lane (untracked)
  ERROR   - a task id appears in more than one lane (ambiguous placement)
  WARNING - a task id referenced in the kanban has no matching task file (dangling)
  WARNING - In Progress count exceeds the WIP cap (default 3)
  WARNING - a known lane heading is entirely missing

Recognised lanes (case-insensitive, any heading depth): Backlog, Ready,
In Progress, In Review, Blocked, Done. A heading containing "validation" is
treated as the release-gate checklist, not a task lane.

Contract (matches the other validators):
  argv in, exit 0 = pass / exit 1 = fail, human summary on stdout.
  --json emits a machine-readable object instead of the human summary.

Usage:
  python validate-kanban.py --path "/abs/path/to/docs/feature-folder"
  python validate-kanban.py "/abs/path/to/docs/feature-folder" --wip 3 --json
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

# Ordered so that more specific "In ..." lanes are tested before short names.
KNOWN_LANES = ("Backlog", "Ready", "In Progress", "In Review", "Blocked", "Done")

HEADING_RE = re.compile(r"^\s{0,3}#{1,6}\s+(.*\S)\s*$")
TASK_ID_RE = re.compile(r"\bT\d+\b", re.IGNORECASE)
TASK_FILE_RE = re.compile(r"^T\d+", re.IGNORECASE)
NOTES_RE = re.compile(r"\.notes\.md$", re.IGNORECASE)


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(add_help=True)
    p.add_argument("--path", dest="path", required=False)
    p.add_argument("positional", nargs="?", default=None)
    p.add_argument("--wip", type=int, default=3, help="In Progress WIP cap (default 3)")
    p.add_argument("--json", dest="as_json", action="store_true")
    return p.parse_args()


def lane_for_heading(heading: str) -> str | None:
    """Return the canonical lane name for a heading, or None."""
    norm = heading.strip().lower()
    if "validation" in norm:
        return None
    for lane in KNOWN_LANES:
        if norm == lane.lower() or norm.startswith(lane.lower()):
            return lane
    return None


def task_ids_from_files(tasks_dir: Path) -> set[str]:
    ids: set[str] = set()
    if not tasks_dir.is_dir():
        return ids
    for f in tasks_dir.iterdir():
        if not f.is_file():
            continue
        if NOTES_RE.search(f.name) or not f.name.lower().endswith(".md"):
            continue
        m = TASK_FILE_RE.match(f.name)
        if m:
            ids.add(m.group(0).upper())
    return ids


def parse_kanban(text: str) -> tuple[dict[str, set[str]], set[str]]:
    """Map canonical lane -> set of task ids referenced under it, and the set of
    lane headings actually present in the document."""
    placements: dict[str, set[str]] = {lane: set() for lane in KNOWN_LANES}
    present: set[str] = set()
    current: str | None = None
    for line in text.splitlines():
        hm = HEADING_RE.match(line)
        if hm:
            current = lane_for_heading(hm.group(1))
            if current:
                present.add(current)
            continue
        if current is None:
            continue
        for tid in TASK_ID_RE.findall(line):
            placements[current].add(tid.upper())
    return placements, present


def build_report(folder: Path, wip_cap: int) -> dict:
    errors: list[str] = []
    warnings: list[str] = []

    kanban = folder / "kanban.md"
    if not kanban.is_file():
        return {
            "ok": False,
            "errors": [f"MISSING: {kanban}"],
            "warnings": [],
            "lane_counts": {},
            "summary": f"INVALID_KANBAN: {kanban} not found.",
        }

    file_ids = task_ids_from_files(folder / "tasks")
    placements, present_lanes = parse_kanban(
        kanban.read_text(encoding="utf-8", errors="replace")
    )

    # Where does each id live?
    id_lanes: dict[str, list[str]] = {}
    for lane, ids in placements.items():
        for tid in ids:
            id_lanes.setdefault(tid, []).append(lane)

    # Untracked: a real task file not placed anywhere.
    for tid in sorted(file_ids):
        if tid not in id_lanes:
            errors.append(f"{tid} has a task file but is not placed in any kanban lane")

    # Ambiguous: placed in more than one lane.
    for tid, lanes in sorted(id_lanes.items()):
        if len(lanes) > 1:
            errors.append(f"{tid} appears in multiple lanes: {', '.join(sorted(lanes))}")

    # Dangling: referenced in kanban but no task file.
    for tid in sorted(id_lanes):
        if file_ids and tid not in file_ids:
            warnings.append(f"{tid} is referenced in the kanban but has no tasks/{tid}-*.md file")

    # Missing lanes.
    for lane in KNOWN_LANES:
        if lane not in present_lanes:
            warnings.append(f'lane "{lane}" heading not found in kanban.md')

    # WIP cap.
    in_progress = len(placements["In Progress"])
    if in_progress > wip_cap:
        warnings.append(f"In Progress has {in_progress} tasks (WIP cap {wip_cap})")

    lane_counts = {lane: len(ids) for lane, ids in placements.items()}
    tracked = len({tid for ids in placements.values() for tid in ids})

    ok = not errors
    summary = (
        f"{'OK' if ok else 'INVALID_KANBAN'}: {tracked} task(s) tracked, "
        f"{len(file_ids)} task file(s). "
        + ", ".join(f"{k}={v}" for k, v in lane_counts.items())
    )
    return {
        "ok": ok,
        "errors": errors,
        "warnings": warnings,
        "lane_counts": lane_counts,
        "summary": summary,
    }


def main() -> int:
    args = parse_args()
    path_str = args.path or args.positional
    if not path_str:
        print("USAGE: validate-kanban.py --path <folder> [--wip N] [--json]")
        return 1

    folder = Path(path_str)
    if not folder.is_dir():
        msg = f"MISSING_FOLDER: {folder}"
        print(json.dumps({"ok": False, "errors": [msg]}) if args.as_json else msg)
        return 1

    report = build_report(folder, args.wip)

    if args.as_json:
        print(json.dumps(report, indent=2))
    else:
        print(report["summary"])
        for e in report["errors"]:
            print(f"  ERROR:   {e}")
        for w in report["warnings"]:
            print(f"  WARNING: {w}")

    return 0 if report["ok"] else 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""check-dod.py

Definition-of-Done checker for a single geeky-implement task. Embodies "verify,
don't trust": instead of believing the agent that a task is finished, assert the
durable signals on disk before the task may move to Done.

Checks for task <ID> in <folder> (missing => ERROR unless noted):
  - a per-task notes file tasks/<ID>-*.notes.md exists
  - <ID> is placed in the Done lane of kanban.md
  - handoff.md mentions <ID>
  - WARNING if <ID> still appears in a non-Done lane (In Progress / Blocked / ...)

It also extracts and prints the task's "Tests/Validation Before Next Task" block
so the orchestrator can re-run those commands itself (this script does not execute
them — running is the caller's job, kept framework- and shell-agnostic).

Contract: argv in, exit 0 = pass / exit 1 = fail, human summary on stdout.
  --json emits a machine-readable object.

Usage:
  python check-dod.py --path "/abs/docs/feature" --task T3
  python check-dod.py "/abs/docs/feature" T3 --json
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

KNOWN_LANES = ("Backlog", "Ready", "In Progress", "In Review", "Blocked", "Done")
HEADING_RE = re.compile(r"^\s{0,3}#{1,6}\s+(.*\S)\s*$")


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(add_help=True)
    p.add_argument("--path", dest="path")
    p.add_argument("--task", dest="task")
    p.add_argument("pos_path", nargs="?", default=None)
    p.add_argument("pos_task", nargs="?", default=None)
    p.add_argument("--json", dest="as_json", action="store_true")
    return p.parse_args()


def lane_for_heading(heading: str) -> str | None:
    norm = heading.strip().lower()
    if "validation" in norm:
        return None
    for lane in KNOWN_LANES:
        if norm == lane.lower() or norm.startswith(lane.lower()):
            return lane
    return None


def lanes_for_task(kanban_text: str, task_id: str) -> list[str]:
    found: list[str] = []
    current: str | None = None
    tid_re = re.compile(rf"\b{re.escape(task_id)}\b", re.IGNORECASE)
    for line in kanban_text.splitlines():
        hm = HEADING_RE.match(line)
        if hm:
            current = lane_for_heading(hm.group(1))
            continue
        if current and tid_re.search(line) and current not in found:
            found.append(current)
    return found


def extract_validation_block(task_text: str) -> str:
    lines = task_text.splitlines()
    start = None
    for i, line in enumerate(lines):
        if re.search(r"Tests\s*/\s*Validation", line, re.IGNORECASE):
            start = i + 1
            break
    if start is None:
        return ""
    out: list[str] = []
    for line in lines[start:]:
        # Stop at the next section label (Estimate:/Priority:/heading).
        if re.match(r"^\s*[#*\s]*(Estimate|Priority)\b", line, re.IGNORECASE):
            break
        if re.match(r"^\s{0,3}#{1,6}\s+\S", line):
            break
        out.append(line)
    return "\n".join(out).strip()


def main() -> int:
    args = parse_args()
    path_str = args.path or args.pos_path
    task_id = (args.task or args.pos_task or "").upper()
    if not path_str or not task_id:
        print("USAGE: check-dod.py --path <folder> --task <ID> [--json]")
        return 1

    folder = Path(path_str)
    if not folder.is_dir():
        msg = f"MISSING_FOLDER: {folder}"
        print(json.dumps({"ok": False, "errors": [msg]}) if args.as_json else msg)
        return 1

    errors: list[str] = []
    warnings: list[str] = []

    # 1. notes file
    tasks_dir = folder / "tasks"
    notes = []
    if tasks_dir.is_dir():
        notes = [f.name for f in tasks_dir.iterdir()
                 if f.is_file() and re.match(rf"^{re.escape(task_id)}\b", f.name, re.IGNORECASE)
                 and f.name.lower().endswith(".notes.md")]
    if not notes:
        errors.append(f"no per-task notes file tasks/{task_id}-*.notes.md")

    # 2/4. kanban placement
    kanban = folder / "kanban.md"
    lanes: list[str] = []
    if not kanban.is_file():
        errors.append("kanban.md not found")
    else:
        lanes = lanes_for_task(kanban.read_text(encoding="utf-8", errors="replace"), task_id)
        if "Done" not in lanes:
            errors.append(f"{task_id} is not in the Done lane (found in: {', '.join(lanes) or 'no lane'})")
        non_done = [l for l in lanes if l != "Done"]
        if non_done:
            warnings.append(f"{task_id} also appears in: {', '.join(non_done)}")

    # 3. handoff mention
    handoff = folder / "handoff.md"
    if not handoff.is_file():
        warnings.append("handoff.md not found")
    elif not re.search(rf"\b{re.escape(task_id)}\b", handoff.read_text(encoding="utf-8", errors="replace"), re.IGNORECASE):
        warnings.append(f"handoff.md does not mention {task_id}")

    # validation block (informational)
    validation = ""
    if tasks_dir.is_dir():
        for f in tasks_dir.iterdir():
            if (f.is_file() and re.match(rf"^{re.escape(task_id)}\b", f.name, re.IGNORECASE)
                    and f.name.lower().endswith(".md") and not f.name.lower().endswith(".notes.md")):
                validation = extract_validation_block(f.read_text(encoding="utf-8", errors="replace"))
                break

    ok = not errors
    summary = f"{'DOD_OK' if ok else 'DOD_INCOMPLETE'}: {task_id}"

    if args.as_json:
        print(json.dumps({
            "ok": ok, "task": task_id, "errors": errors, "warnings": warnings,
            "lanes": lanes, "validation_block": validation,
        }, indent=2))
    else:
        print(summary)
        for e in errors:
            print(f"  ERROR:   {e}")
        for w in warnings:
            print(f"  WARNING: {w}")
        if validation:
            print("  Re-run this task's validation block (verify, don't trust):")
            for line in validation.splitlines():
                print(f"    | {line}")

    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())

"""Command-line entry point for wordstat."""

from __future__ import annotations

import argparse
import sys

from .analyzer import analyze
from .output import render_json, render_text


def positive_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError as error:
        raise argparse.ArgumentTypeError(f"{value!r} is not an integer") from error
    if parsed < 1:
        raise argparse.ArgumentTypeError("must be at least 1")
    return parsed


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="wordstat")
    parser.add_argument("--json", action="store_true", help="emit JSON output")
    parser.add_argument(
        "--top",
        type=positive_int,
        default=3,
        metavar="N",
        help="number of frequent words to include (default: 3)",
    )
    parser.add_argument("file", metavar="FILE", help="UTF-8 text file to analyze")
    return parser


def fail(message: str, exit_code: int) -> int:
    print(f"wordstat: error: {message}", file=sys.stderr)
    return exit_code


def main(argv: list[str] | None = None) -> int:
    sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    args = build_parser().parse_args(argv)

    try:
        with open(args.file, "r", encoding="utf-8-sig", newline="") as source:
            text = source.read()
    except UnicodeDecodeError:
        return fail(f"{args.file}: not valid UTF-8", 3)
    except OSError:
        return fail(f"{args.file}: cannot read file", 3)

    result = analyze(text, args.top)
    rendered = render_json(result) if args.json else render_text(result)
    sys.stdout.write(rendered)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

