"""Exact text and JSON rendering for analysis results."""

from __future__ import annotations

import json
from typing import Any


def render_text(result: dict[str, Any]) -> str:
    """Render the four-line text format, including its final newline."""
    top = result["top"]
    top_text = " ".join(f"{entry['word']}={entry['count']}" for entry in top)
    top_line = f"top: {top_text}" if top_text else "top:"
    return (
        f"lines: {result['lines']}\n"
        f"words: {result['words']}\n"
        f"chars: {result['chars']}\n"
        f"{top_line}\n"
    )


def render_json(result: dict[str, Any]) -> str:
    """Render the one-line JSON format, including its final newline."""
    return json.dumps(result) + "\n"
